"use client"

import * as React from "react"

import {
  createViewerResource,
  type ViewerContentIdentity,
  type ViewerResource,
} from "@/lib/viewer-resource"
import {
  DEFAULT_MAX_BYTES,
  DEFAULT_MAX_LINES,
} from "@/components/ui/text-viewer-resource"
import type {
  TextViewerHandle,
  TextViewerProps,
} from "@/components/ui/text-viewer-types"
import { ViewerErrorBoundary } from "@/components/ui/viewer-error"

import { TextViewerFallback } from "./text-viewer-chrome"
import { TextViewerContent } from "./text-viewer-content"

export type {
  TextDocumentSource,
  TextLineRange,
  TextViewerHandle,
  TextViewerProps,
} from "@/components/ui/text-viewer-types"

export const TextViewer = React.forwardRef<TextViewerHandle, TextViewerProps>(
  function TextViewer(props, ref) {
    const [retryState, setRetryState] = React.useState({
      contentKey: "",
      version: 0,
    })
    const [isMounted, setIsMounted] = React.useState(false)
    const { source } = props
    const resource = React.useMemo(() => createViewerResource(source), [source])
    const contentBaseKey = textViewerContentBaseKey(resource.content, props)
    const retryVersion =
      retryState.contentKey === contentBaseKey ? retryState.version : 0
    const resetKey = textViewerResetKey(resource, props, retryVersion)
    const contentResetKey = textViewerContentResetKey(
      contentBaseKey,
      retryVersion
    )

    React.useEffect(() => {
      setIsMounted(true)
    }, [])

    if (!isMounted) {
      return (
        <TextViewerFallback
          className={props.className}
          toolbar={props.toolbar}
          bare={props.bare}
        />
      )
    }

    return (
      <ViewerErrorBoundary
        bare={props.bare}
        className={props.className}
        download={
          props.toolbar === false ? null : textViewerDownloadAction(resource)
        }
        format="text"
        resetKey={resetKey}
        sourceKind={resource.sourceKind}
        onRetry={() =>
          setRetryState((state) => ({
            contentKey: contentBaseKey,
            version:
              state.contentKey === contentBaseKey ? state.version + 1 : 1,
          }))
        }
      >
        <React.Suspense
          key={contentResetKey}
          fallback={
            <TextViewerFallback
              className={props.className}
              toolbar={props.toolbar}
              bare={props.bare}
            />
          }
        >
          <TextViewerContent
            {...props}
            forwardedRef={ref}
            retryVersion={retryVersion}
            resource={resource}
          />
        </React.Suspense>
      </ViewerErrorBoundary>
    )
  }
)

function textViewerDownloadAction(resource: ViewerResource) {
  return resource.originalDownload
}

function textViewerResetKey(
  resource: ViewerResource,
  props: Pick<TextViewerProps, "maxBytes" | "maxLines">,
  retryVersion: number
): string {
  const [maxBytesKey, maxLinesKey] = textViewerBoundsResetKey(props)
  return [resource.keys.resource, retryVersion, maxBytesKey, maxLinesKey].join(
    "\u0000"
  )
}

function textViewerContentResetKey(
  contentBaseKey: string,
  retryVersion: number
): string {
  return [contentBaseKey, retryVersion].join("\u0000")
}

function textViewerContentBaseKey(
  content: ViewerContentIdentity,
  props: Pick<TextViewerProps, "maxBytes" | "maxLines">
): string {
  const [maxBytesKey, maxLinesKey] = textViewerBoundsResetKey(props)
  return [content.key, maxBytesKey, maxLinesKey].join("\u0000")
}

function textViewerBoundsResetKey(
  props: Pick<TextViewerProps, "maxBytes" | "maxLines">
) {
  return [
    textViewerBoundResetKeyPart(props.maxBytes, DEFAULT_MAX_BYTES),
    textViewerBoundResetKeyPart(props.maxLines, DEFAULT_MAX_LINES),
  ] as const
}

function textViewerBoundResetKeyPart(
  value: number | undefined,
  defaultValue: number
) {
  return String(value === undefined ? defaultValue : value)
}

"use client"

import * as React from "react"
import { Maximize, Minus, Plus } from "lucide-react"

import { cn } from "@/lib/utils"
import { type ViewerDownloadAction } from "@/lib/viewer-download"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { ViewerDownloadControl } from "@/components/ui/viewer-download"

export function TextViewerFrame({
  className,
  bare,
  children,
}: {
  className?: string
  bare?: boolean
  children: React.ReactNode
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-background" : "rounded-xl border bg-background",
        className
      )}
      data-slot="text-viewer"
    >
      {children}
    </div>
  )
}

export function TextViewerFallback({
  className,
  toolbar = true,
  bare,
}: {
  className?: string
  toolbar?: boolean
  bare?: boolean
}) {
  return (
    <TextViewerFrame className={className} bare={bare}>
      {toolbar ? (
        <div className="flex h-10 flex-shrink-0 items-center gap-2 border-b bg-card px-3">
          <Skeleton className="h-3 w-16" />
          <div className="ml-auto flex items-center gap-2">
            <Skeleton className="h-3 w-10" />
            <Skeleton className="size-5" />
            <Skeleton className="size-5" />
          </div>
        </div>
      ) : null}
      <div
        className="min-h-0 flex-1 space-y-3 overflow-hidden p-5"
        data-slot="text-body-skeleton"
      >
        {Array.from({ length: 10 }, (_, index) => (
          <Skeleton
            key={index}
            className="h-4"
            style={{ width: `${48 + ((index * 17) % 44)}%` }}
          />
        ))}
      </div>
    </TextViewerFrame>
  )
}

export function TextViewerToolbar({
  wordCount,
  fontScale,
  downloadAction,
  onZoomOut,
  onZoomIn,
  onResetZoom,
}: {
  wordCount: number
  fontScale: number
  downloadAction: ViewerDownloadAction
  onZoomOut: () => void
  onZoomIn: () => void
  onResetZoom: () => void
}) {
  return (
    <TextViewerToolbarFrame
      leading={`${wordCount} word${wordCount === 1 ? "" : "s"}`}
      trailing={
        <>
          <TextViewerZoomControls
            fontScale={fontScale}
            onZoomOut={onZoomOut}
            onZoomIn={onZoomIn}
            onResetZoom={onResetZoom}
          />
          <div className="mx-1 h-4 w-px bg-border" />
          <ViewerDownloadControl actions={[downloadAction]} />
        </>
      }
    />
  )
}

function TextViewerToolbarFrame({
  leading,
  trailing,
}: {
  leading: React.ReactNode
  trailing: React.ReactNode
}) {
  return (
    <div className="flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
      <span className="px-1 text-xs text-muted-foreground tabular-nums">
        {leading}
      </span>
      <div className="ml-auto flex items-center gap-1">{trailing}</div>
    </div>
  )
}

function TextViewerZoomControls({
  fontScale,
  disabled = false,
  onZoomOut,
  onZoomIn,
  onResetZoom,
}: {
  fontScale: number
  disabled?: boolean
  onZoomOut?: () => void
  onZoomIn?: () => void
  onResetZoom?: () => void
}) {
  const disabledProps = disabled
    ? ({ disabled: true, tabIndex: -1, "aria-hidden": true } as const)
    : {}

  return (
    <>
      <IconButton
        label="Zoom out"
        onClick={disabled ? undefined : onZoomOut}
        {...disabledProps}
      >
        <Minus />
      </IconButton>
      <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
        {Math.round(fontScale * 100)}%
      </span>
      <IconButton
        label="Zoom in"
        onClick={disabled ? undefined : onZoomIn}
        {...disabledProps}
      >
        <Plus />
      </IconButton>
      <IconButton
        label="Reset zoom"
        onClick={disabled ? undefined : onResetZoom}
        {...disabledProps}
      >
        <Maximize />
      </IconButton>
    </>
  )
}

function IconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import type { ViewerResource } from "@/lib/viewer-resource"
import { ScrollArea } from "@/components/ui/scroll-area"
import { TextViewerToolbar } from "@/components/ui/text-viewer-chrome"
import {
  isLineInRange,
  normalizeTextLineRange,
} from "@/components/ui/text-viewer-ranges"
import {
  readTextResource,
  resolvedTextViewerBounds,
  splitTextLines,
} from "@/components/ui/text-viewer-resource"

import { TextViewerFrame } from "./text-viewer-chrome"
import { layoutTextLines } from "./text-viewer-layout"
import {
  clampTextViewerScale,
  TEXT_VIEWER_BLOCK_PADDING,
} from "./text-viewer-scale"
import type { TextViewerHandle, TextViewerProps } from "./text-viewer-types"
import {
  getTextScrollAnchor,
  useTextVariableVirtualizer,
  type TextScrollAnchor,
} from "./text-viewer-virtualization"

const TEXT_VIEWER_BASE_FONT_PX = 15
const TEXT_VIEWER_BASE_LINE_PX = 24
const TEXT_VIEWER_HORIZONTAL_PADDING = 16
const TEXT_VIEWER_INITIAL_TEXT_WIDTH = 768
const TEXT_VIEWER_OVERSCAN = 6
const TEXT_VIEWER_FONT_FAMILY = "Arial, sans-serif"
const TEXT_VIEWER_FONT_NAME = "Arial"

export function TextViewerContent({
  resource,
  className,
  toolbar = true,
  highlight,
  bare = false,
  maxBytes,
  maxLines,
  retryVersion,
  forwardedRef,
}: TextViewerProps & {
  resource: ViewerResource
  retryVersion: number
  forwardedRef?: React.ForwardedRef<TextViewerHandle>
}) {
  const bounds = resolvedTextViewerBounds({ maxBytes, maxLines })
  const text = readTextResource({
    content: resource.content,
    retryVersion,
    bounds,
  })
  const textLines = React.useMemo(() => splitTextLines(text), [text])
  const wordCount = React.useMemo(() => countTextWords(text), [text])
  const highlightStart = highlight?.start
  const highlightEnd = highlight?.end
  const highlightRange = React.useMemo(
    () =>
      normalizeTextLineRange(
        highlightStart == null || highlightEnd == null
          ? null
          : { start: highlightStart, end: highlightEnd },
        textLines.length
      ),
    [highlightStart, highlightEnd, textLines.length]
  )
  const downloadAction = React.useMemo(
    () => resource.originalDownload,
    [resource]
  )

  const [fontScale, setFontScale] = React.useState(1)
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const pendingScrollAnchorRef = React.useRef<TextScrollAnchor | null>(null)
  const fontSize = TEXT_VIEWER_BASE_FONT_PX * fontScale
  const lineHeight = TEXT_VIEWER_BASE_LINE_PX * fontScale
  const [contentWidth, setContentWidth] = React.useState(
    TEXT_VIEWER_INITIAL_TEXT_WIDTH
  )
  const lineLayouts = React.useMemo(
    () =>
      layoutTextLines({
        contentWidth,
        fontName: TEXT_VIEWER_FONT_NAME,
        fontSize,
        lineHeight,
        textLines,
      }),
    [contentWidth, fontSize, lineHeight, textLines]
  )
  const itemSizes = React.useMemo(
    () => lineLayouts.map((lineLayout) => lineLayout.height),
    [lineLayouts]
  )
  const { offsets, totalSize, virtualItems, viewportWidth } =
    useTextVariableVirtualizer({
      itemSizes,
      overscan: TEXT_VIEWER_OVERSCAN,
      paddingEnd: TEXT_VIEWER_BLOCK_PADDING,
      paddingStart: TEXT_VIEWER_BLOCK_PADDING,
      scrollRef: viewportRef,
    })

  const captureScrollAnchor = React.useCallback(() => {
    pendingScrollAnchorRef.current = getTextScrollAnchor({
      itemSizes,
      offsets,
      scrollTop: viewportRef.current?.scrollTop ?? 0,
    })
  }, [itemSizes, offsets])

  React.useLayoutEffect(() => {
    const nextContentWidth = Math.max(
      1,
      viewportWidth - TEXT_VIEWER_HORIZONTAL_PADDING * 2
    )
    setContentWidth((current) => {
      if (current === nextContentWidth) return current
      captureScrollAnchor()
      return nextContentWidth
    })
  }, [captureScrollAnchor, viewportWidth])

  React.useLayoutEffect(() => {
    const anchor = pendingScrollAnchorRef.current
    const scrollElement = viewportRef.current
    if (!anchor || !scrollElement) return

    pendingScrollAnchorRef.current = null
    const nextStart = offsets.starts[anchor.index]
    const nextSize = itemSizes[anchor.index]
    if (nextStart == null || nextSize == null) return

    scrollElement.scrollTop = Math.max(
      0,
      nextStart + Math.min(anchor.offsetWithinLine, Math.max(0, nextSize - 1))
    )
  }, [itemSizes, offsets])

  const scrollLineRange = React.useCallback(
    (
      range: ReturnType<typeof normalizeTextLineRange>,
      options?: ScrollToOptions
    ) => {
      const scrollElement = viewportRef.current
      if (!scrollElement || !range) return
      const startIndex = range.start - 1
      const endIndex = range.end - 1
      const startTop = offsets.starts[startIndex]
      const endTop = offsets.starts[endIndex]
      const endHeight = itemSizes[endIndex]
      if (startTop == null || endTop == null || endHeight == null) return

      const rangeBottom = endTop + endHeight
      const rangeHeight = rangeBottom - startTop
      const targetTop =
        rangeHeight <= scrollElement.clientHeight
          ? startTop - (scrollElement.clientHeight - rangeHeight) / 2
          : startTop

      scrollElement.scrollTo({
        top: Math.max(0, targetTop),
        behavior: "smooth",
        ...options,
      })
    },
    [itemSizes, offsets]
  )

  const zoom = (factor: number) => {
    captureScrollAnchor()
    setFontScale((scale) => clampTextViewerScale(scale * factor))
  }

  const resetZoom = () => {
    captureScrollAnchor()
    setFontScale(1)
  }

  React.useImperativeHandle(
    forwardedRef,
    () => ({
      scrollToLineRange: (range, options) => {
        scrollLineRange(
          normalizeTextLineRange(range, textLines.length),
          options
        )
      },
      getViewportElement: () => viewportRef.current,
    }),
    [scrollLineRange, textLines.length]
  )

  React.useEffect(() => {
    scrollLineRange(highlightRange)
  }, [highlightRange, scrollLineRange])

  return (
    <TextViewerFrame className={className} bare={bare}>
      {toolbar ? (
        <TextViewerToolbar
          wordCount={wordCount}
          fontScale={fontScale}
          downloadAction={downloadAction}
          onZoomOut={() => zoom(1 / 1.2)}
          onZoomIn={() => zoom(1.2)}
          onResetZoom={resetZoom}
        />
      ) : null}
      <ScrollArea
        className="min-h-0 flex-1 bg-background"
        orientation="vertical"
        viewportClassName="bg-background"
        viewportRef={viewportRef}
      >
        <div
          className="relative min-w-0"
          data-slot="text-virtual-canvas"
          style={{
            height: totalSize,
            minWidth: viewportWidth,
          }}
        >
          {virtualItems.map((item) => {
            const lineNumber = item.index + 1
            return (
              <TextLineBlock
                key={item.key}
                fontSize={fontSize}
                isHighlighted={isLineInRange(lineNumber, highlightRange)}
                lineHeight={lineHeight}
                lineNumber={lineNumber}
                text={textLines[item.index] ?? ""}
                style={{
                  height: item.size,
                  transform: `translateY(${item.start}px)`,
                }}
              />
            )
          })}
        </div>
      </ScrollArea>
    </TextViewerFrame>
  )
}

function TextLineBlock({
  fontSize,
  isHighlighted,
  lineHeight,
  lineNumber,
  style,
  text,
}: {
  fontSize: number
  isHighlighted: boolean
  lineHeight: number
  lineNumber: number
  style: React.CSSProperties
  text: string
}) {
  return (
    <div
      data-source-line={lineNumber}
      data-slot="text-line"
      className={cn(
        "absolute top-0 left-0 w-full px-4",
        isHighlighted && "bg-primary/12 ring-1 ring-primary/30 ring-inset"
      )}
      style={style}
    >
      <span
        className="block min-w-0 wrap-break-word whitespace-pre-wrap text-foreground"
        style={{
          fontFamily: TEXT_VIEWER_FONT_FAMILY,
          fontSize,
          lineHeight: `${lineHeight}px`,
          tabSize: 8,
        }}
      >
        {text || " "}
      </span>
    </div>
  )
}

function countTextWords(text: string) {
  const matches = text.trim().match(/\S+/g)
  return matches?.length ?? 0
}

"use client"

import { layout, prepare } from "@chenglou/pretext"

export interface TextLineLayout {
  height: number
}

export interface TextLayoutOptions {
  contentWidth: number
  fontName: string
  fontSize: number
  lineHeight: number
  textLines: readonly string[]
}

const TEXT_LAYOUT_CACHE_LIMIT = 50_000
const textLayoutHeightCache = new Map<string, number>()

export function layoutTextLines({
  contentWidth,
  fontName,
  fontSize,
  lineHeight,
  textLines,
}: TextLayoutOptions): TextLineLayout[] {
  return textLines.map((line) => ({
    height: measureTextLineHeight({
      contentWidth,
      fontName,
      fontSize,
      lineHeight,
      text: line,
    }),
  }))
}

export function measureTextLineHeight({
  contentWidth,
  fontName,
  fontSize,
  lineHeight,
  text,
}: {
  contentWidth: number
  fontName: string
  fontSize: number
  lineHeight: number
  text: string
}) {
  const cacheKey = [
    Math.round(contentWidth),
    Math.round(fontSize * 100) / 100,
    Math.round(lineHeight * 100) / 100,
    fontName,
    text,
  ].join("\u0000")
  const cachedHeight = textLayoutHeightCache.get(cacheKey)
  if (cachedHeight != null) return cachedHeight

  const height = measureTextLineHeightUncached({
    contentWidth,
    fontName,
    fontSize,
    lineHeight,
    text,
  })
  textLayoutHeightCache.set(cacheKey, height)
  trimTextLayoutHeightCache()
  return height
}

function measureTextLineHeightUncached({
  contentWidth,
  fontName,
  fontSize,
  lineHeight,
  text,
}: {
  contentWidth: number
  fontName: string
  fontSize: number
  lineHeight: number
  text: string
}) {
  try {
    const font = `400 ${fontSize}px ${fontName}`
    const prepared = prepare(text || " ", font, { whiteSpace: "pre-wrap" })
    return Math.max(
      lineHeight,
      layout(prepared, contentWidth, lineHeight).height
    )
  } catch {
    return estimateWrappedHeight({ contentWidth, lineHeight, text })
  }
}

export function estimateWrappedHeight({
  contentWidth,
  lineHeight,
  text,
}: {
  contentWidth: number
  lineHeight: number
  text: string
}) {
  const averageGlyphWidth = lineHeight * 0.45
  const columns = Math.max(1, Math.floor(contentWidth / averageGlyphWidth))
  const visualLineCount = Math.max(
    1,
    text.split("\n").reduce((count, line) => {
      return count + Math.max(1, Math.ceil((line || " ").length / columns))
    }, 0)
  )
  return visualLineCount * lineHeight
}

function trimTextLayoutHeightCache() {
  while (textLayoutHeightCache.size > TEXT_LAYOUT_CACHE_LIMIT) {
    const firstKey = textLayoutHeightCache.keys().next().value
    if (firstKey == null) return
    textLayoutHeightCache.delete(firstKey)
  }
}

"use client"

import * as React from "react"
import { Download } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  ViewerDownloadError,
  type ViewerDownloadAction,
  type ViewerDownloadPayload,
} from "@/lib/viewer-download"
import { Button, buttonVariants } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

export interface TriggerViewerDownloadOptions {
  signal?: AbortSignal
}

export async function triggerViewerDownload(
  action: ViewerDownloadAction,
  options?: TriggerViewerDownloadOptions
): Promise<void> {
  if (action.isDisabled) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "disabled",
      message: "This download is disabled.",
    })
  }

  let payload: ViewerDownloadPayload
  try {
    payload = await action.getPayload(options)
  } catch (error) {
    if (isAbortError(error)) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "aborted",
        message: "Download was cancelled.",
        cause: error,
      })
    }
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "payload_failed",
      message: "Could not prepare this download.",
      cause: error,
    })
  }

  if (payload.kind === "none") return
  if (payload.kind === "href") {
    try {
      clickDownload(payload.href, action.fileName)
    } catch (error) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "unsupported",
        message: "Could not start this download.",
        cause: error,
      })
    }
    return
  }

  try {
    const blob =
      payload.kind === "blob"
        ? payload.blob
        : new Blob([payload.text], {
            type: payload.mimeType ?? "text/plain;charset=utf-8",
          })
    const url = URL.createObjectURL(blob)
    try {
      clickDownload(url, action.fileName)
    } finally {
      URL.revokeObjectURL(url)
    }
  } catch (error) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "unsupported",
      message: "Could not start this download.",
      cause: error,
    })
  }
}

export type ViewerDownloadErrorHandler = (
  error: ViewerDownloadError,
  action: ViewerDownloadAction
) => void

export interface ViewerDownloadTrigger {
  pendingActionId: string | null
  triggerDownload: (action: ViewerDownloadAction) => void
}

export interface ViewerDownloadTriggerOptions {
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler
  resetKey?: unknown
}

export interface ViewerDownloadControlProps {
  actions: Array<ViewerDownloadAction | null | undefined>
  variant?: React.ComponentProps<typeof Button>["variant"]
  size?: React.ComponentProps<typeof Button>["size"]
  className?: string
  showLabel?: boolean
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler
}

export interface ViewerDownloadButtonProps extends Omit<
  ViewerDownloadControlProps,
  "actions"
> {
  action: ViewerDownloadAction | null
}

export interface ViewerDownloadMenuProps extends Omit<
  ViewerDownloadControlProps,
  "actions"
> {
  actions: ViewerDownloadAction[]
}

export function useViewerDownloadHref(
  action: ViewerDownloadAction | null
): string | null {
  const shouldCreateHref = action?.origin !== "derived"
  const payload = shouldCreateHref ? getSynchronousPayload(action) : null

  return shouldCreateHref && payload?.kind === "href" ? payload.href : null
}

export function useViewerDownloadTrigger({
  onError,
  resetKey = "",
}: ViewerDownloadTriggerOptions = {}): ViewerDownloadTrigger {
  const [pendingActionId, setPendingActionId] = React.useState<string | null>(
    null
  )
  const abortControllerRef = React.useRef<AbortController | null>(null)

  React.useEffect(() => {
    return () => {
      abortControllerRef.current?.abort()
      abortControllerRef.current = null
    }
  }, [resetKey])

  const triggerDownload = React.useCallback(
    (action: ViewerDownloadAction) => {
      abortControllerRef.current?.abort()
      const abortController = new AbortController()
      abortControllerRef.current = abortController
      setPendingActionId(action.id)
      void triggerViewerDownload(action, { signal: abortController.signal })
        .catch((error) => {
          reportDownloadError(error, action, onError)
        })
        .finally(() => {
          if (abortControllerRef.current === abortController) {
            abortControllerRef.current = null
            setPendingActionId(null)
          }
        })
    },
    [onError]
  )

  return { pendingActionId, triggerDownload }
}

export function ViewerDownloadControl({
  actions,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadControlProps) {
  const enabledActions = actions.filter(
    (action): action is ViewerDownloadAction => Boolean(action)
  )

  if (enabledActions.length <= 1) {
    return (
      <ViewerDownloadButton
        action={enabledActions[0] ?? null}
        variant={variant}
        size={size}
        className={className}
        showLabel={showLabel}
        onError={onError}
      />
    )
  }

  return (
    <ViewerDownloadMenu
      actions={enabledActions}
      variant={variant}
      size={size}
      className={className}
      showLabel={showLabel}
      onError={onError}
    />
  )
}

export function ViewerDownloadButton({
  action,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadButtonProps) {
  const href = useViewerDownloadHref(action)
  const label = action?.label ?? "Download"
  const disabled = !action || action.isDisabled
  const hasDownloadHref = Boolean(href)
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: action,
  })
  const isPending = Boolean(action && pendingActionId === action.id)

  const handleClick = React.useCallback(() => {
    if (!action || hasDownloadHref) return
    triggerDownload(action)
  }, [action, hasDownloadHref, triggerDownload])

  if (href) {
    return (
      <a
        href={href}
        download={action?.fileName}
        className={cn(buttonVariants({ variant, size }), className)}
        aria-label={label}
        title={label}
        data-slot="button"
      >
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
        {showLabel ? label : null}
      </a>
    )
  }

  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      aria-label={label}
      title={label}
      disabled={disabled}
      loading={isPending}
      onClick={handleClick}
    >
      <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
      {showLabel ? label : null}
    </Button>
  )
}

export function ViewerDownloadMenu({
  actions,
  variant = "ghost",
  size = "icon-sm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadMenuProps) {
  const actionSetKey = actions.map((action) => action.id).join("\u0000")
  const label = "Download"
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: actionSetKey,
  })

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant={variant}
            size={size}
            className={className}
            aria-label={label}
            title={label}
            loading={pendingActionId != null}
          >
            <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
            {showLabel ? label : null}
          </Button>
        }
      />
      <DropdownMenuContent align="end">
        {actions.map((action) => (
          <DropdownMenuItem
            key={action.id}
            disabled={action.isDisabled || pendingActionId != null}
            onClick={() => triggerDownload(action)}
          >
            <Download />
            <span>{action.label}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function clickDownload(href: string, fileName: string) {
  const anchor = document.createElement("a")
  anchor.href = href
  anchor.download = fileName
  anchor.rel = "noreferrer"
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
}

function getSynchronousPayload(
  action: ViewerDownloadAction | null
): ViewerDownloadPayload | null {
  if (!action || action.isDisabled) return null
  const payload = action.getPayload()
  return payload instanceof Promise ? null : payload
}

function reportDownloadError(
  error: unknown,
  action: ViewerDownloadAction,
  onError: ViewerDownloadErrorHandler | undefined
) {
  if (!(error instanceof ViewerDownloadError)) return
  if (error.kind === "aborted") return
  onError?.(error, action)
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError"
}

export interface TextLineRange {
  start: number
  end: number
}

export interface NormalizedTextLineRange extends TextLineRange {
  readonly normalized: true
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

export function normalizeTextLineRange(
  range: TextLineRange | null | undefined,
  lineCount: number
): NormalizedTextLineRange | null {
  if (
    !range ||
    !Number.isFinite(range.start) ||
    !Number.isFinite(range.end) ||
    !Number.isFinite(lineCount) ||
    lineCount <= 0
  ) {
    return null
  }

  const maxLine = Math.floor(lineCount)
  const rawStart = Math.trunc(range.start)
  const rawEnd = Math.trunc(range.end)
  const start = Math.min(rawStart, rawEnd)
  const end = Math.max(rawStart, rawEnd)

  if (end < 1 || start > maxLine) return null

  return {
    start: clamp(start, 1, maxLine),
    end: clamp(end, 1, maxLine),
    normalized: true,
  }
}

export function isLineInRange(
  lineNumber: number,
  range: NormalizedTextLineRange | null
) {
  return range != null && lineNumber >= range.start && lineNumber <= range.end
}

import {
  isResourceError,
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors"
import type {
  ViewerContentIdentity,
  ViewerContentPayload,
  ViewerContentText,
} from "@/lib/viewer-resource"

export const DEFAULT_MAX_BYTES = 1_000_000
export const DEFAULT_MAX_LINES = 10_000
export const MAX_TEXT_RESOURCE_CACHE_ENTRIES = 64

export interface TextViewerBounds {
  maxBytes?: number
  maxLines?: number
}

export type TextViewerTooLargeReason = "bytes" | "lines"
export type TextViewerBoundName = "maxBytes" | "maxLines"

export class TextViewerTooLargeError extends ViewerFormatError {
  readonly reason: TextViewerTooLargeReason

  constructor(reason: TextViewerTooLargeReason) {
    super({
      format: "text",
      kind: "bounds",
      message: `Text file exceeds ${reason} limit`,
    })
    this.name = "TextViewerTooLargeError"
    this.reason = reason
  }
}

export class TextViewerInvalidBoundsError extends ViewerFormatError {
  readonly boundName: TextViewerBoundName

  constructor(boundName: TextViewerBoundName) {
    super({
      format: "text",
      kind: "bounds",
      message: `${boundName} must be a positive integer`,
    })
    this.name = "TextViewerInvalidBoundsError"
    this.boundName = boundName
  }
}

export function toTextFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions = {
    kind: "load_failed",
    message: "Failed to load text.",
  }
): ViewerFormatError {
  if (isViewerFormatError(error)) return error
  return new ViewerFormatError({
    format: "text",
    kind: options.kind,
    message: options.message,
    cause: error,
  })
}

interface TextResource {
  promise: Promise<string>
  status: "pending" | "resolved" | "rejected"
  value?: string
  error?: unknown
}

const textResourceCache = new Map<string, TextResource>()

export type TextViewerContent = ViewerContentIdentity &
  ViewerContentPayload &
  ViewerContentText

function textViewerResourceKey({
  content,
  retryVersion,
  bounds,
}: {
  content: ViewerContentIdentity
  retryVersion: number
  bounds: Required<TextViewerBounds>
}) {
  return `${content.key}\0${retryVersion}\0${bounds.maxBytes}\0${bounds.maxLines}`
}

export function clearTextViewerResourceCacheForTests() {
  textResourceCache.clear()
}

export function resolvedTextViewerBounds({
  maxBytes = DEFAULT_MAX_BYTES,
  maxLines = DEFAULT_MAX_LINES,
}: TextViewerBounds = {}): Required<TextViewerBounds> {
  return {
    maxBytes: resolveTextViewerBound(maxBytes, "maxBytes"),
    maxLines: resolveTextViewerBound(maxLines, "maxLines"),
  }
}

export function assertTextWithinBounds(
  text: string,
  bounds: Required<TextViewerBounds>
) {
  if (new TextEncoder().encode(text).byteLength > bounds.maxBytes) {
    throw new TextViewerTooLargeError("bytes")
  }
  if (lineCountOf(text) > bounds.maxLines) {
    throw new TextViewerTooLargeError("lines")
  }
}

// Split into stable source lines. The prose viewer may wrap each source line
// into several visual lines, but highlighting and scroll APIs stay source-line
// based.
export function splitTextLines(text: string) {
  return text.split(/\r\n|[\n\r\u2028\u2029]/g)
}

export function readTextResource({
  content,
  retryVersion,
  bounds,
}: {
  content: TextViewerContent
  retryVersion: number
  bounds: Required<TextViewerBounds>
}) {
  const inlineText = inlineTextResource(content)
  if (inlineText != null) {
    assertTextWithinBounds(inlineText, bounds)
    return inlineText
  }

  const resourceKey = textViewerResourceKey({ content, retryVersion, bounds })
  const textResource = getTextResource({ content, resourceKey, bounds })

  if (textResource.status === "resolved") return textResource.value ?? ""
  if (textResource.status === "rejected") throw textResource.error

  throw textResource.promise
}

function inlineTextResource(content: ViewerContentPayload) {
  return content.payload.kind === "text" ? content.payload.text : null
}

function getTextResource({
  content,
  resourceKey,
  bounds,
}: {
  content: TextViewerContent
  resourceKey: string
  bounds: Required<TextViewerBounds>
}) {
  let textResource = textResourceCache.get(resourceKey)
  if (!textResource) {
    const nextResource: TextResource = {
      status: "pending",
      promise: readBoundedTextResource(content, bounds),
    }
    nextResource.promise.then(
      (value) => {
        nextResource.status = "resolved"
        nextResource.value = value
      },
      (error) => {
        nextResource.status = "rejected"
        nextResource.error = error
      }
    )
    textResource = nextResource
    textResourceCache.set(resourceKey, textResource)
    trimTextResourceCache()
  }
  return textResource
}

async function readBoundedTextResource(
  content: ViewerContentText,
  bounds: Required<TextViewerBounds>
) {
  try {
    return await content.readText(bounds)
  } catch (error) {
    if (isResourceError(error)) throw error
    throw toTextFormatError(error)
  }
}

function lineCountOf(text: string) {
  return splitTextLines(text).length
}

function resolveTextViewerBound(value: number, boundName: TextViewerBoundName) {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new TextViewerInvalidBoundsError(boundName)
  }
  return value
}

function trimTextResourceCache() {
  while (textResourceCache.size > MAX_TEXT_RESOURCE_CACHE_ENTRIES) {
    const firstKey = textResourceCache.keys().next().value
    if (firstKey === undefined) return
    textResourceCache.delete(firstKey)
  }
}

export const TEXT_VIEWER_MIN_SCALE = 0.25
export const TEXT_VIEWER_MAX_SCALE = 5
export const TEXT_VIEWER_BLOCK_PADDING = 8

export function clampTextViewerScale(value: number) {
  return Math.min(TEXT_VIEWER_MAX_SCALE, Math.max(TEXT_VIEWER_MIN_SCALE, value))
}

